fn create_smart_contract_engine(gas_price: i32, gas_limit: i32) -> SmartContractEngine {
    return SmartContractEngine {
        contracts: [],
        transactions: [],
        gas_price: gas_price,
        gas_limit: gas_limit,
        state_changes: []
    };
}

fn deploy_contract(engine: SmartContractEngine, address: string, code: string, initial_balance: i32, created_at: i32) -> SmartContractEngine {
    let contract = ContractState {
        address: address,
        code: code,
        storage: [],
        balance: initial_balance,
        nonce: 0,
        created_at: created_at
    };

    push(engine.contracts, contract);
    let mut result = engine;
    return result;
}

fn find_contract_index(engine: SmartContractEngine, address: string) -> i32 {
    let i = 0;
    while i < length(engine.contracts) {
        if engine.contracts[i].address == address {
            return i;
        }
        i = i + 1;
    }
    return -1;
}

fn get_contract_state(engine: SmartContractEngine, address: string) -> ContractState {
    let idx = find_contract_index(engine, address);
    if idx == -1 {
        return ContractState {
            address: "",
            code: "",
            storage: [],
            balance: 0,
            nonce: 0,
            created_at: 0
        };
    }

    return engine.contracts[idx];
}

fn set_contract_storage(engine: SmartContractEngine, address: string, key: string, value: i32) -> SmartContractEngine {
    let idx = find_contract_index(engine, address);
    if idx == -1 {
        return engine;
    }

    let contract = engine.contracts[idx];
    push(contract.storage, key);
    push(contract.storage, value);

    let mut result = engine;
    result.contracts[idx] = contract;

    let change = key + "=" + value;
    push(result.state_changes, change);

    return result;
}

fn get_contract_storage(engine: SmartContractEngine, address: string, key: string) -> i32 {
    let idx = find_contract_index(engine, address);
    if idx == -1 {
        return 0;
    }

    let contract = engine.contracts[idx];
    let i = 0;

    while i < length(contract.storage) {
        if contract.storage[i] == key && i + 1 < length(contract.storage) {
            return contract.storage[i + 1];
        }
        i = i + 2;
    }

    return 0;
}

fn execute_transaction(engine: SmartContractEngine, tx: Transaction) -> ContractExecution {
    let contract_idx = find_contract_index(engine, tx.to);

    if contract_idx == -1 {
        return ContractExecution {
            contract_address: tx.to,
            caller: tx.from,
            method: "",
            args: [],
            gas_used: 0,
            result: "contract_not_found",
            success: false
        };
    }

    let contract = engine.contracts[contract_idx];

    let gas_used = calculate_gas(tx.data);
    if gas_used > tx.gas_limit {
        return ContractExecution {
            contract_address: tx.to,
            caller: tx.from,
            method: "",
            args: [],
            gas_used: gas_used,
            result: "out_of_gas",
            success: false
        };
    }

    let method = parse_method(tx.data);
    let result = execute_method(contract, method, tx.value);

    return ContractExecution {
        contract_address: tx.to,
        caller: tx.from,
        method: method,
        args: [],
        gas_used: gas_used,
        result: result,
        success: true
    };
}

fn calculate_gas(data: string) -> i32 {
    let gas = 21000;  // Base transaction gas
    let i = 0;

    while i < length(data) {
        if data[i] == 48 {  // '0'
            gas = gas + 4;
        } else {
            gas = gas + 16;
        }
        i = i + 1;
    }

    return gas;
}

fn parse_method(data: string) -> string {
    if length(data) < 8 {
        return "";
    }

    let method = "";
    let i = 0;
    while i < 8 && i < length(data) {
        method = method + data[i];
        i = i + 1;
    }

    return method;
}

fn execute_method(contract: ContractState, method: string, value: i32) -> string {
    if method == "" {
        return "invalid_method";
    }

    // Simple method execution based on signature
    if method == "transfe" {  // transfer
        return execute_transfer(contract, value);
    }

    if method == "balancO" {  // balance
        return execute_balance(contract);
    }

    if method == "increM" {  // increment
        return execute_increment(contract);
    }

    return "unknown_method";
}

fn execute_transfer(contract: ContractState, amount: i32) -> string {
    if contract.balance < amount {
        return "insufficient_balance";
    }

    contract.balance = contract.balance - amount;
    return "transfer_success";
}

fn execute_balance(contract: ContractState) -> string {
    return "balance:" + contract.balance;
}

fn execute_increment(contract: ContractState) -> string {
    contract.balance = contract.balance + 1;
    return "incremented";
}

fn send_transaction(engine: SmartContractEngine, tx: Transaction) -> SmartContractEngine {
    push(engine.transactions, tx);
