}

fn get_total_gas_used(engine: SmartContractEngine) -> i32 {
    let total = 0;
    let i = 0;

    while i < length(engine.transactions) {
        let tx = engine.transactions[i];
        total = total + calculate_gas(tx.data);
        i = i + 1;
    }

    return total;
}

fn calculate_transaction_fee(engine: SmartContractEngine, gas_used: i32) -> i32 {
    return gas_used * engine.gas_price;
}

fn validate_contract_code(code: string) -> bool {
    if length(code) == 0 {
        return false;
    }

    // Simple validation: check code length and patterns
    let i = 0;
    let balance = 0;

    while i < length(code) {
        if code[i] == 40 {  // '('
            balance = balance + 1;
        } else if code[i] == 41 {  // ')'
            balance = balance - 1;
        }

        if balance < 0 {
            return false;
        }

        i = i + 1;
    }

    return balance == 0;
}

fn get_contract_balance(engine: SmartContractEngine, address: string) -> i32 {
    let contract = get_contract_state(engine, address);
    return contract.balance;
}

fn add_contract_balance(engine: SmartContractEngine, address: string, amount: i32) -> SmartContractEngine {
    let idx = find_contract_index(engine, address);
    if idx == -1 {
        return engine;
