    let contract = engine.contracts[idx];
    contract.balance = contract.balance + amount;

    let mut result = engine;
    result.contracts[idx] = contract;

    return result;
}

fn revert_contract_state(engine: SmartContractEngine, address: string) -> SmartContractEngine {
    let idx = find_contract_index(engine, address);
    if idx == -1 {
        return engine;
    }

    let contract = engine.contracts[idx];
    contract.storage = [];

    let mut result = engine;
    result.contracts[idx] = contract;

    return result;
}

fn get_contract_nonce(engine: SmartContractEngine, address: string) -> i32 {
    let contract = get_contract_state(engine, address);
    return contract.nonce;
}

fn increment_contract_nonce(engine: SmartContractEngine, address: string) -> SmartContractEngine {
    let idx = find_contract_index(engine, address);
    if idx == -1 {
        return engine;
    }

    let contract = engine.contracts[idx];
    contract.nonce = contract.nonce + 1;

    let mut result = engine;
    result.contracts[idx] = contract;

    return result;
}

fn get_engine_stats(engine: SmartContractEngine) -> any {
